using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _sut;

    public OrderServiceTests()
    {
        _sut = new OrderService();
    }

    private static List<OrderItem> CreateItems(int count = 1) =>
        Enumerable.Range(1, count)
            .Select(i => new OrderItem
            {
                ProductName = $"Product {i}",
                Price = 10m * i,
                Quantity = i
            })
            .ToList();

    #region CreateOrder - Happy Path

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectCustomerId()
    {
        // Arrange
        var items = CreateItems();

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        Assert.AreEqual("customer-1", order.CustomerId);
    }

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithNonEmptyId()
    {
        // Arrange
        var items = CreateItems();

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        Assert.IsNotNull(order.Id);
        Assert.AreNotEqual(string.Empty, order.Id);
    }

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithSameItems()
    {
        // Arrange
        var items = CreateItems(2);

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        Assert.AreSame(items, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithSingleItem_CalculatesTotalCorrectly()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Widget", Price = 25.50m, Quantity = 3 }
        };

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        Assert.AreEqual(76.50m, order.Total);
    }

    [TestMethod]
    public void CreateOrder_WithMultipleItems_SumsTotalCorrectly()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "A", Price = 10m, Quantity = 2 },
            new() { ProductName = "B", Price = 5m, Quantity = 4 }
        };

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        Assert.AreEqual(40m, order.Total); // (10*2) + (5*4)
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentUtcTime()
    {
        // Arrange
        var before = DateTime.UtcNow;
        var items = CreateItems();

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        var after = DateTime.UtcNow;
        Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after);
    }

    #endregion

    #region CreateOrder - Validation

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        // Arrange
        var items = CreateItems();

        // Act & Assert
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        // Act & Assert
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder("customer-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        // Act & Assert
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _sut.CreateOrder("customer-1", []));
        Assert.AreEqual("Cannot create an order with no items.", ex.Message);
    }

    #endregion

    #region GetOrder

    [TestMethod]
    public void GetOrder_WithExistingId_ReturnsMatchingOrder()
    {
        // Arrange
        var created = _sut.CreateOrder("customer-1", CreateItems());

        // Act
        var retrieved = _sut.GetOrder(created.Id);

        // Assert
        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_WithNonExistingId_ReturnsNull()
    {
        // Act
        var result = _sut.GetOrder("nonexistent-id");

        // Assert
        Assert.IsNull(result);
    }

    #endregion

    #region GetOrdersByCustomer

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        // Act
        var result = _sut.GetOrdersByCustomer("customer-1");

        // Assert
        Assert.IsEmpty(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithMultipleOrders_ReturnsAllForCustomer()
    {
        // Arrange
        _sut.CreateOrder("customer-1", CreateItems());
        _sut.CreateOrder("customer-1", CreateItems());
        _sut.CreateOrder("customer-2", CreateItems());

        // Act
        var result = _sut.GetOrdersByCustomer("customer-1");

        // Assert
        Assert.HasCount(2, result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_DoesNotReturnOtherCustomerOrders()
    {
        // Arrange
        var otherOrder = _sut.CreateOrder("customer-2", CreateItems());
        _sut.CreateOrder("customer-1", CreateItems());

        // Act
        var result = _sut.GetOrdersByCustomer("customer-1");

        // Assert
        Assert.DoesNotContain(otherOrder, result);
    }

    #endregion

    #region Data-Driven Total Calculation

    [TestMethod]
    [DynamicData(nameof(TotalCalculationData))]
    public void CreateOrder_CalculatesExpectedTotal(decimal price, int quantity, decimal expectedTotal)
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Item", Price = price, Quantity = quantity }
        };

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        Assert.AreEqual(expectedTotal, order.Total);
    }

    public static IEnumerable<(decimal price, int quantity, decimal expectedTotal)> TotalCalculationData =>
    [
        (10m, 1, 10m),
        (5.99m, 3, 17.97m),
        (0.01m, 100, 1.00m),
        (999.99m, 1, 999.99m),
    ];

    #endregion
}

